class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses ReadItem for single-partition reads and
        // sync I/O now throws by default. Use async or opt-in to sync.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 5: Patch-based updates are now default in EF 9.
        // SaveChanges sends partial patch requests instead of full document replace.
        // No code change needed (faster), but be aware if you rely on full-doc replace.
        context.SaveChanges();
    }

    // Preferred: async pattern avoids sync-over-async issues in EF 9 Cosmos.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

